mapper.select:
SELECT 
FROM employee e
LEFT JOIN workplace w ON w.id = e.workplace_id
LEFT JOIN department d ON d.id = e.department_id
LEFT JOIN employee_external_mapping m
  ON m.employee_id = e.id AND m.tenant_id = e.tenant_id AND m.status = 'ACTIVE'
WHERE e.tenant_id = #{tenantId}

  AND (e.employee_no LIKE CONCAT('%', #{query.keyword}, '%') OR e.employee_name LIKE CONCAT('%', #{query.keyword}, '%'))


  AND e.department_id = #{query.departmentId}


  AND e.employment_type = #{query.employmentType}


  AND e.status = #{query.status}

ORDER BY e.employee_no ASC, e.id ASC

SELECT FROM employee e LEFT JOIN workplace w ON w.id = e.workplace_id LEFT JOIN department d ON d.id = e.department_id LEFT JOIN employee_external_mapping m ON m.employee_id = e.id AND m.tenant_id = e.tenant_id AND m.status = 'ACTIVE' WHERE e.tenant_id = #{tenantId} AND m.external_employee_id = #{externalEmployeeId}
AND m.source_system = #{sourceSystem}
ORDER BY e.id ASC LIMIT 1

