DELETE FROM employee_work_rule
WHERE tenant_id = #{tenantId}
  AND employee_id = #{employeeId}

DELETE FROM employee_external_mapping
WHERE tenant_id = #{tenantId}
  AND employee_id = #{employeeId}

DELETE FROM employee
WHERE tenant_id = #{tenantId}
  AND id = #{id}

