mapper.update:
UPDATE employee_work_rule
SET work_rule_type = #{workRuleType},
    standard_daily_minutes = #{dailyMinutes},
    standard_weekly_minutes = #{weeklyMinutes},
    overtime_enabled = 1,
    night_work_enabled = CASE WHEN #{dailyMinutes} >= 480 THEN 1 ELSE 0 END,
    holiday_work_enabled = CASE WHEN #{dailyMinutes} >= 480 THEN 1 ELSE 0 END,
    effective_start_date = #{effectiveStartDate}
WHERE tenant_id = #{tenantId}
  AND employee_id = #{employeeId}

